/// Every `menu()` declared by a vendored `.dbd`, keyed by its EPICS name.
///
/// This is the table `get_enum_strs` answers a `DBF_MENU` field from: the
/// field's [`FieldDesc::menu`] already points at its choices, and this map
/// exists for the by-name lookups (`.db` loading, `dbpr`).
pub fn menu_choices(menu: &str) -> Option<&'static [&'static str]> {
    Some(match menu {
        "digitelBAKS" => MENU_DIGITEL_BAKS,
        "digitelBKIN" => MENU_DIGITEL_BKIN,
        "digitelCMOR" => MENU_DIGITEL_CMOR,
        "digitelDSPL" => MENU_DIGITEL_DSPL,
        "digitelKLCK" => MENU_DIGITEL_KLCK,
        "digitelMODR" => MENU_DIGITEL_MODR,
        "digitelMODS" => MENU_DIGITEL_MODS,
        "digitelPTYP" => MENU_DIGITEL_PTYP,
        "digitelS1MS" => MENU_DIGITEL_S1_MS,
        "digitelS1VS" => MENU_DIGITEL_S1_VS,
        "digitelS3BS" => MENU_DIGITEL_S3_BS,
        "digitelSET1" => MENU_DIGITEL_SET1,
        "digitelTYPE" => MENU_DIGITEL_TYPE,
        "vsOFFON" => MENU_VS_OFFON,
        "vsTYPE" => MENU_VS_TYPE,
        _ => return None,
    })
}

